 static Texture2D SurfaceTexture(string name,Color a,Color b,bool brick=false){int size=512;var tex=new Texture2D(size,size,TextureFormat.RGBA32,true,false){name=name,wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Trilinear,anisoLevel=2};var colors=new Color32[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++){float noise=Mathf.PerlinNoise(x*.14f,y*.14f)*.5f+Mathf.PerlinNoise(x*.034f,y*.034f)*.5f;var color=Color.Lerp(a,b,noise);if(brick){int row=y/32;int xx=(x+(row%2)*64)%128;float edge=Mathf.Min(xx,127-xx,y%32,31-y%32);if(edge<2)color=Color.Lerp(C(.23f,.21f,.18f),color,edge/2);else color*=.83f+(Mathf.Sin(row*87.3f+(x+(row%2)*64)/128*21.1f)*.5f+.5f)*.28f;}colors[y*size+x]=color;}tex.SetPixels32(colors);tex.Apply(true,true);return tex;}
