 static Batch GetBatch(string material,Vector3 p){
  // Compare partitions on identical authored geometry; this is a mesh-count measurement, not an FPS estimate.
  legacyBatchKeys.Add(material+"_"+Mathf.FloorToInt((p.z+48)/16));
  bool distant=p.z< -49||p.z>56;
  bool translucentOrFoliage=material=="water"||material=="leaf"||material=="leafLight";
  bool smallUnshadowed=material=="bulb"||material=="amber"||material=="neon"||material=="paper";
  float cell=material=="streetBrick"?8:distant||translucentOrFoliage?16:smallUnshadowed?64:16;
  string key=material+"_"+(distant?"distant_":"near_")+Mathf.FloorToInt((p.z+48)/cell);
  if(!batches.TryGetValue(key,out var batch)){batch=new Batch{material=mats[material]};batches.Add(key,batch);}return batch;
 }

 static void Box(string name,Vector3 p,Vector3 size,string material,bool solid=false,Quaternion? rotation=null){var q=rotation??Quaternion.identity;var b=GetBatch(material,p);var h=size*.5f;Vector3[] normals={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};Vector3[] u={Vector3.back,Vector3.forward,Vector3.right,Vector3.right,Vector3.right,Vector3.left};Vector3[] v={Vector3.up,Vector3.up,Vector3.back,Vector3.forward,Vector3.up,Vector3.up};for(int f=0;f<6;f++){int k=b.v.Count;var nn=normals[f];var uu=u[f];var vv=v[f];var center=Vector3.Scale(nn,h);float su=Vector3.Scale(uu,h).magnitude,sv=Vector3.Scale(vv,h).magnitude;foreach(var xy in new[]{new Vector2(-1,-1),new Vector2(1,-1),new Vector2(1,1),new Vector2(-1,1)}){b.v.Add(p+q*(center+uu*su*xy.x+vv*sv*xy.y));b.n.Add(q*nn);b.uv.Add(new Vector2((xy.x+1)*su,(xy.y+1)*sv));}b.t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}
  if(solid){var go=new GameObject(name);go.transform.SetParent(root,false);go.transform.localPosition=p;go.transform.localRotation=q;go.AddComponent<BoxCollider>().size=size;}detailCount++;
 }
 static void Cylinder(string name,Vector3 a,Vector3 b,float radius,string material,int sides=8){var q=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);var batch=GetBatch(material,a);float len=(b-a).magnitude;for(int i=0;i<sides;i++){float t=i*Mathf.PI*2/sides,t2=(i+1)*Mathf.PI*2/sides;Vector3 n1=q*new Vector3(Mathf.Cos(t),0,Mathf.Sin(t)),n2=q*new Vector3(Mathf.Cos(t2),0,Mathf.Sin(t2));int k=batch.v.Count;batch.v.AddRange(new[]{a+n1*radius,b+n1*radius,b+n2*radius,a+n2*radius});batch.n.AddRange(new[]{n1,n1,n2,n2});batch.uv.AddRange(new[]{new Vector2(0,0),new Vector2(0,len),new Vector2(1,len),new Vector2(1,0)});batch.t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}detailCount++;}
