 static void Ellipsoid(Vector3 p,Vector3 scale,string material,int segments=9,int rings=5){var batch=GetBatch(material,p);for(int y=0;y<rings;y++)for(int x=0;x<segments;x++){int k=batch.v.Count;foreach(var uv in new[]{new Vector2(x,y),new Vector2(x+1,y),new Vector2(x+1,y+1),new Vector2(x,y+1)}){float a=uv.x/segments*Mathf.PI*2,b=uv.y/rings*Mathf.PI;var n=new Vector3(Mathf.Sin(b)*Mathf.Cos(a),Mathf.Cos(b),Mathf.Sin(b)*Mathf.Sin(a));batch.v.Add(p+Vector3.Scale(n,scale));batch.n.Add(new Vector3(n.x/scale.x,n.y/scale.y,n.z/scale.z).normalized);batch.uv.Add(uv/new Vector2(segments,rings));}batch.t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}detailCount++;}
 static void Puddle(Vector3 p,float rx,float rz){var batch=GetBatch("water",p);int k=batch.v.Count;batch.v.Add(p);batch.n.Add(Vector3.up);batch.uv.Add(Vector2.zero);for(int i=0;i<=20;i++){float a=i/20f*Mathf.PI*2;float wav=1+Mathf.Sin(a*3+.4f)*.17f+Mathf.Sin(a*7)*.09f;batch.v.Add(p+new Vector3(Mathf.Cos(a)*rx*wav,0,Mathf.Sin(a)*rz*wav));batch.n.Add(Vector3.up);batch.uv.Add(new Vector2(Mathf.Cos(a),Mathf.Sin(a)));}for(int i=0;i<20;i++)batch.t.AddRange(new[]{k,k+i+2,k+i+1});}
