 public static GameObject Build(Transform parent){Materials();Spots.Clear();RouteStarts.Clear();RoofRoutes.Clear();batches.Clear();legacyBatchKeys.Clear();random=new System.Random(46);detailCount=0;var go=new GameObject("Ballard Avenue — closing time");go.transform.SetParent(parent,false);root=go.transform;
  DenGround();foreach(int side in new[]{-1,1}){Box("Granite sidewalk",new(side*7.5f,.10f,9),new(4,.2f,94),"paving",true);for(int z=-38;z<54;z+=2){Box("Granite curb",new(side*5.55f,.12f,z),new(.20f,.26f,1.96f),"stone");Box("Paving seam",new(side*7.4f,.206f,z),new(3.65f,.009f,.016f),"iron");}for(int row=0;row<5;row++)Building(side,row);for(int row=0;row<5;row++){float z=-31+row*16;PoleLamp(new(side*5.95f,.22f,z));Tree(new(side*6.35f,.22f,z+7));Planter(new(side*8.0f,.22f,z+2.8f));}}
  BrickAvenue();
  // Heritage brick surface with wet patches and exposed streetcar seams.
  // Dampness is shaded directly on the brick: no floating asphalt-colored puddle overlays.
  foreach(float x in new[]{-1.0f,1.0f})Box("Old streetcar seam",new(x,.012f,2),new(.035f,.012f,91),"iron");
  for(int i=0;i<13;i++)Box("Crosswalk paint",new(-4.6f+i*.76f,.009f,40),new(.44f,.01f,2),"cream");
  // Patio chairs, tables and closing-time sidewalk clutter.
  foreach(int side in new[]{-1,1})foreach(float z in new[]{-24f,7f,25f}){var p=new Vector3(side*7.55f,.22f,z);Box("Cafe table",p+Vector3.up*.74f,new(.86f,.08f,.74f),"cedar");Cylinder("Table pedestal",p,p+Vector3.up*.7f,.06f,"iron");for(int j=-1;j<=1;j+=2){var chair=p+Vector3.forward*j*.8f;Box("Chair seat",chair+Vector3.up*.42f,new(.43f,.06f,.43f),"wood");Box("Chair back",chair+new Vector3(0,.7f,j*.2f),new(.43f,.5f,.05f),"wood");foreach(int k in new[]{-1,1})foreach(int leg in new[]{-1,1})Cylinder("Chair legs",chair+new Vector3(k*.17f,0,leg*.17f),chair+new Vector3(k*.17f,.43f,leg*.17f),.025f,"iron");}Box("Folded menu",p+Vector3.up*.83f,new(.21f,.015f,.3f),"paper");}
  // Overhead festoons define the street ceiling and pull the eye toward the next block.
  foreach(float z in new[]{-18f,14f,37f})for(int i=0;i<18;i++){float x=-9+i*1.05f,y=6.3f-Mathf.Sin(i/17f*Mathf.PI)*.85f;Cylinder("Festoon wire",new(x,y,z),new(x+1.05f,6.3f-Mathf.Sin((i+1)/17f*Mathf.PI)*.85f,z),.012f,"iron",5);Ellipsoid(new(x,y-.10f,z),new(.047f,.063f,.047f),"bulb",10,6);}
  foreach(float z in new[]{-18f,14f,37f})foreach(float x in new[]{-5.5f,0f,5.5f})Light(new(x,5.2f,z),C(1,.78f,.52f),8.5f,8.0f);
  Den();BellGarden();ParkEdges();LivingGardens();RoofPersonalization();RoundTripWayfinding();Backdrop();Bake();go.AddComponent<ClosingWorldCleanup>().ownedMeshes=createdMeshes.ToArray();createdMeshes.Clear();Debug.Log("CLOSING_TIME_WORLD details="+detailCount+" legacy16mBatches="+legacyBatchKeys.Count+" batches="+batches.Count+" spots="+Spots.Count+" roofRoutes="+RoofRoutes.Count);batches.Clear();legacyBatchKeys.Clear();return go;
 }
 static readonly List<Mesh> createdMeshes=new();
 static void Bake(){foreach(var pair in batches){var b=pair.Value;var m=new Mesh{name="Ballard "+pair.Key,indexFormat=IndexFormat.UInt32};m.SetVertices(b.v);m.SetNormals(b.n);m.SetUVs(0,b.uv);m.SetTriangles(b.t,0);m.RecalculateBounds();m.RecalculateTangents();m.UploadMeshData(Application.isPlaying);createdMeshes.Add(m);var go=new GameObject("Architecture "+pair.Key);go.transform.SetParent(root,false);go.AddComponent<MeshFilter>().sharedMesh=m;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=b.material;r.shadowCastingMode=pair.Key.StartsWith("window")||pair.Key.StartsWith("glass")||pair.Key.StartsWith("bulb")||pair.Key.StartsWith("lanternGlass")||pair.Key.StartsWith("amber")||pair.Key.StartsWith("neon")||pair.Key.StartsWith("water")||pair.Key.StartsWith("paper")?ShadowCastingMode.Off:ShadowCastingMode.On;r.receiveShadows=true;}}
 static void Den(){DenRoom();}
 static void Bell(){foreach(float x in new[]{-1f,1f})Cylinder("Marvins bell frame",new(x,0,-43),new(x,6.7f,-43),.12f,"iron");Cylinder("Bell lintel",new(-1.3f,6.5f,-43),new(1.3f,6.5f,-43),.12f,"iron");for(int i=0;i<5;i++){float y=5.6f+i*.18f;Box("Historic bell",new(0,y,-43),new(1.25f-i*.17f,.20f,.85f-i*.09f),"gold");}Text("MARVIN'S GARDEN",new(0,1.2f,-42.5f),.036f,"cream",Quaternion.Euler(0,180,0));PoleLamp(new(-2.5f,0,-42));}
