 public static void ConfigureAtmosphere(Camera cam,Transform parent){cam.backgroundColor=C(.018f,.036f,.07f);cam.clearFlags=CameraClearFlags.Skybox;cam.farClipPlane=330;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=C(.14f,.19f,.27f);RenderSettings.ambientEquatorColor=C(.080f,.105f,.14f);RenderSettings.ambientGroundColor=C(.03f,.04f,.055f);RenderSettings.fog=true;RenderSettings.fogColor=C(.035f,.075f,.12f);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.0055f;
  var moon=new GameObject("Moonlight");moon.transform.SetParent(parent,false);moon.transform.rotation=Quaternion.Euler(58,-32,0);var light=moon.AddComponent<Light>();light.type=LightType.Directional;light.color=C(.73f,.83f,1);light.intensity=1.15f;light.shadows=LightShadows.Soft;light.shadowStrength=.82f;light.shadowBias=.035f;light.shadowNormalBias=.20f;var moonData=moon.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalLightData>();moonData.usePipelineSettings=false;moonData.softShadowQuality=UnityEngine.Rendering.Universal.SoftShadowQuality.Low;RenderSettings.sun=light;
  var shader=Shader.Find("Jimothy/ClosingTimeSky");if(shader){var sky=new Material(shader);sky.SetVector("_MoonDirection",-light.transform.forward);RenderSettings.skybox=sky;}else{var sky=new Material(Shader.Find("Skybox/Procedural"));sky.SetColor("_SkyTint",C(.06f,.12f,.25f));sky.SetFloat("_Exposure",.2f);RenderSettings.skybox=sky;}
  var volume=parent.gameObject.AddComponent<ClosingAtmosphere>();volume.Initialize(cam,RenderSettings.skybox);
 }
