public class ClosingLight:MonoBehaviour {
 Light lamp;float power;void Awake(){lamp=GetComponent<Light>();power=lamp.intensity;}
 void Update(){var g=GameSession.Instance;if(!g||!g.Player)return;float distance=Vector3.Distance(g.Player.transform.position,transform.position);float fade=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(20,30,distance));lamp.enabled=fade>.001f;lamp.intensity=power*fade;}
}
public class ClosingWorldCleanup:MonoBehaviour {public Mesh[] ownedMeshes;void OnDestroy(){if(ownedMeshes!=null)foreach(var m in ownedMeshes)if(m)Destroy(m);}}
public class ClosingAtmosphere:MonoBehaviour {Material ownedSky;VolumeProfile ownedProfile;void OnDestroy(){if(ownedSky){if(RenderSettings.skybox==ownedSky)RenderSettings.skybox=null;Destroy(ownedSky);}if(ownedProfile){foreach(var component in ownedProfile.components)if(component)Destroy(component);Destroy(ownedProfile);}}public void Initialize(Camera camera,Material sky){ownedSky=sky;var data=camera.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();if(!data)data=camera.gameObject.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();data.renderPostProcessing=true;var v=gameObject.AddComponent<Volume>();v.isGlobal=true;v.priority=2;ownedProfile=ScriptableObject.CreateInstance<VolumeProfile>();v.sharedProfile=ownedProfile;var bloom=ownedProfile.Add<UnityEngine.Rendering.Universal.Bloom>();bloom.intensity.Override(.34f);bloom.threshold.Override(1.35f);bloom.scatter.Override(.5f);var tone=ownedProfile.Add<UnityEngine.Rendering.Universal.Tonemapping>();tone.mode.Override(UnityEngine.Rendering.Universal.TonemappingMode.ACES);var color=ownedProfile.Add<UnityEngine.Rendering.Universal.ColorAdjustments>();color.postExposure.Override(.25f);color.contrast.Override(10);color.saturation.Override(-3);}}
